<script setup lang="ts">
import { computed, onMounted, onUnmounted, nextTick, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { open } from '@tauri-apps/api/dialog'
import { useAppStore } from '@/stores/app'
import { useArchiveLibraryStore } from '@/stores/archiveLibrary'
import { libraryBytes, libraryStatus, libraryAvailability, type LibraryHit, type LibrarySource, type LibraryCredentials } from '@/types/archiveLibrary'
import { storeToRefs } from 'pinia'
import { useLibraryRetrievalStore } from '@/stores/libraryRetrieval'
import LibraryRetrievalDialog from '@/components/archive/LibraryRetrievalDialog.vue'
import LibraryOrganizeDialog from '@/components/archive/LibraryOrganizeDialog.vue'
import LibraryCredentialsDialog from '@/components/archive/LibraryCredentialsDialog.vue'
import { isZipPasswordEncoding } from '@/types/zipPassword'
import { useArchiveBrowserCapabilities } from '@/composables/useArchiveBrowserCapabilities'
import Modal from '@/components/ui/Modal.vue'
import WorkspaceHeader from '@/components/ui/WorkspaceHeader.vue'

const library = useArchiveLibraryStore(), app = useAppStore(), router = useRouter()
const capabilities = useArchiveBrowserCapabilities(); void capabilities.refresh()
const credentialId = ref(''), pendingHit = ref<{ hit: LibraryHit; action: 'locate' | 'preview' | 'extract' | 'read' } | null>(null)
const credentialSource = computed(() => library.sources.find(row => row.id === credentialId.value))
const credentialError = computed(() => credentialSource.value?.note || library.error)
const { workspace } = storeToRefs(library)
const libraryTab = computed({ get: () => workspace.value.view || 'search', set: (value: 'search' | 'sources') => { workspace.value.view = value; workspace.value.scrollTop = 0; if (pageElement.value) pageElement.value.scrollTop = 0 } })
const filterCount = computed(() => Number(!!library.sourceId) + Number(library.category !== 'all') + Number(!!library.tag) + Number(library.favoritesOnly))
const expanded = computed({get:()=>workspace.value.expanded,set:value=>workspace.value.expanded=value}), sourcePage=computed({get:()=>workspace.value.sourcePage,set:value=>workspace.value.sourcePage=value}), sourceSearch=computed({get:()=>workspace.value.sourceSearch,set:value=>workspace.value.sourceSearch=value}), removing=ref<LibrarySource|null>(null)
const pageElement=ref<HTMLElement|null>(null),organizing=ref<LibrarySource|null>(null),retrievalVisible=ref(false),savingSearch=ref(false),searchName=ref(''),savedSearchId=ref('')
const retrieval=useLibraryRetrievalStore()
const candidatesVisible = ref(false), candidatePage = ref(1), candidateSelection = ref(new Set<string>()), opening = ref('')
const filteredSources = computed(() => library.sources.filter(row => `${row.name} ${row.path}`.toLowerCase().includes(sourceSearch.value.toLowerCase())))
const sourcePages = computed(() => Math.max(1, Math.ceil(filteredSources.value.length / 20)))
const visibleSources = computed(() => filteredSources.value.slice((sourcePage.value - 1) * 20, sourcePage.value * 20))
const candidates = computed(() => library.scanResult?.candidates || [])
const candidatePages = computed(() => Math.max(1, Math.ceil(candidates.value.length / 50)))
const visibleCandidates = computed(() => candidates.value.slice((candidatePage.value - 1) * 50, candidatePage.value * 50))
const resultPages = computed(() => Math.max(1, Math.ceil(library.total / 50)))
const busy = computed(() => library.loading || library.indexing || library.scanning || library.checking)
let timer: ReturnType<typeof setTimeout> | undefined
watch([() => library.query, () => library.sourceId, () => library.category, () => library.tag, () => library.favoritesOnly], () => {
  clearTimeout(timer); library.page = 1; timer = setTimeout(() => void library.search(), 220)
})
watch(sourceSearch, () => { sourcePage.value = 1 })
watch(sourcePages, value => { sourcePage.value = Math.min(value, sourcePage.value) })
onMounted(async () => {await library.initialize();await nextTick();if(pageElement.value)pageElement.value.scrollTop=workspace.value.scrollTop})
onUnmounted(() => clearTimeout(timer))
const queuedSelection = () => import.meta.env.VITE_DESKTOP_E2E ? window.__LONG_DECOMPRESS_DESKTOP_E2E__?.takeDesktopDialogSelection() : undefined
async function addFiles() {
  const queued = queuedSelection()
  const paths = queued === undefined ? await open({ multiple: true, filters: [{ name: '可浏览归档及分卷', extensions: [...new Set([...capabilities.browseExtensions.value, '001', 'z01', 'r00'])] }, { name: '所有文件', extensions: ['*'] }] }) : queued
  if (paths && await library.add(Array.isArray(paths) ? paths : [paths])) libraryTab.value = 'sources'
}
async function scanFolder() {
  const queued = queuedSelection()
  const directory = queued === undefined ? await open({ directory: true }) : queued
  if (typeof directory !== 'string') return
  await library.scan(directory)
  if (library.scanResult) { candidatePage.value = 1; candidateSelection.value = new Set(candidates.value.map(row => row.path)); candidatesVisible.value = true }
}
function toggleCandidate(path: string) {
  const next = new Set(candidateSelection.value); next.has(path) ? next.delete(path) : next.add(path); candidateSelection.value = next
}
async function addCandidates() {
  if (await library.add([...candidateSelection.value])) { candidatesVisible.value = false; libraryTab.value = 'sources' }
}
async function removeSource() {
  if (removing.value && await library.remove(removing.value.id)) removing.value = null
}
async function openHit(hit: LibraryHit, action: 'locate' | 'preview' | 'extract' | 'read') {
  if (opening.value) return
  opening.value = `${hit.sourceId}:${hit.path}`
  try {
    if (!await library.check(hit)) { revealSource(hit.sourceId); return }
    const source = library.sources.find(row => row.id === hit.sourceId)
    if (source?.encrypted && !library.credentials[hit.sourceId]?.password) { pendingHit.value = { hit, action }; credentialId.value = hit.sourceId; return }
    const credential = library.credentials[hit.sourceId]
    const savedEncoding = source?.sourceEncoding
    app.openArchiveInBrowser(source?.path || hit.sourcePath, { librarySourceId: hit.sourceId, focusEntryPath: hit.path, entryAction: action, password: credential?.password, zipPasswordEncoding: credential?.encoding || (isZipPasswordEncoding(savedEncoding) ? savedEncoding : undefined) })
    await router.push('/browser')
  } finally { opening.value = '' }
}
function revealSource(id: string) { libraryTab.value = 'sources'; sourceSearch.value = ''; expanded.value = id; const index = library.sources.findIndex(row => row.id === id); sourcePage.value = Math.max(1, Math.floor(index / 20) + 1) }
function showCredentials(row: LibrarySource) { pendingHit.value = null; credentialId.value = row.id }
function refreshSource(row: LibrarySource) { if (row.status === 'locked' && !library.credentials[row.id]?.password) showCredentials(row); else void library.index([row.id]) }
async function applyCredentials(value: LibraryCredentials) {
  const id = credentialId.value; library.setCredentials(id, value); await library.index([id])
  if (library.sources.find(row => row.id === id)?.status !== 'ready') return
  credentialId.value = ''; const pending = pendingHit.value; pendingHit.value = null
  if (pending) await openHit(pending.hit, pending.action)
}
async function relocateSource(row: LibrarySource) {
  const queued = queuedSelection(), picked = queued === undefined ? await open({ title: '重新定位归档或任意分卷成员', multiple: false }) : queued
  const path = Array.isArray(picked) ? picked[0] : picked
  if (typeof path === 'string' && await library.relocate(row.id, path)) revealSource(row.id)
}
function fixRetrieval(id:string){retrievalVisible.value=false;revealSource(id);const row=library.sources.find(row=>row.id===id);if(row?.encrypted)showCredentials(row)}
async function saveSearch(){if(await library.saveSearch(searchName.value)){savingSearch.value=false;searchName.value=''}}
async function resultPage(value: number) { library.page = value; await library.search() }
</script>

<template>
  <div ref="pageElement" class="module-page library-page custom-scrollbar" data-testid="archive-library" @scroll="workspace.scrollTop = ($event.target as HTMLElement).scrollTop">
    <WorkspaceHeader title="归档资源库" description="跨包查找文件，打开查看或直接取回。" icon="pi pi-database">
      <button class="lib-button" data-testid="library-add-files" :disabled="busy" @click="addFiles"><i class="pi pi-plus" />添加压缩包</button>
      <button class="lib-button primary" data-testid="library-scan-folder" :disabled="busy" @click="scanFolder"><i class="pi pi-folder-open" />扫描目录</button>
    </WorkspaceHeader>
    <div class="library-nav">
      <nav class="module-tabs" aria-label="资料库视图"><button :class="{active:libraryTab==='search'}" :aria-pressed="libraryTab==='search'" data-testid="library-search-tab" @click="libraryTab='search'"><i class="pi pi-search"/>跨包搜索</button><button :class="{active:libraryTab==='sources'}" :aria-pressed="libraryTab==='sources'" data-testid="library-sources-tab" @click="libraryTab='sources'"><i class="pi pi-box"/>资料管理<span class="module-count">{{ library.sources.length }}</span></button></nav>
      <div class="library-stats"><span><strong>{{ library.ready.length }}</strong> 份可搜索</span><span><strong>{{ library.ready.reduce((sum, row) => sum + row.entryCount, 0).toLocaleString() }}</strong> 个文件</span></div>
    </div>
    <div v-if="library.error" class="lib-message error" role="alert" data-testid="library-error"><i class="pi pi-exclamation-circle" /><span>{{ library.error }}</span><button class="lib-link" @click="library.error = ''">关闭</button></div>
    <div v-if="library.notice" class="lib-message" role="status" data-testid="library-notice"><i class="pi pi-info-circle" /><span>{{ library.notice }}</span><button class="lib-link" @click="library.notice = ''">关闭</button></div>
    <section v-if="library.indexing || library.scanning || library.checking" class="library-progress" data-testid="library-progress" aria-live="polite">
      <div class="flex items-center gap-3"><i class="pi pi-spin pi-spinner text-primary" /><div class="min-w-0"><strong>{{ library.scanning ? '正在查找归档候选' : library.paused ? (library.activeSource ? '当前来源完成后暂停' : '已暂停，可稍后继续') : `${library.checking ? '正在检查来源' : '正在读取资料并建立索引'} · ${library.completed} / ${library.planned}` }}</strong><p v-if="library.indexing" class="text-muted text-xs break-all mt-1">{{ library.sources.find(row => row.id === library.activeSource)?.name }}</p><p class="text-muted text-xs mt-1">可以切换页面，已完成来源可继续搜索</p></div></div>
      <button v-if="!library.scanning" class="lib-button" data-testid="library-pause" :disabled="library.stopRequested" @click="library.paused ? library.resume() : library.pause()">{{ library.paused ? '继续' : '暂停' }}</button><button class="lib-button" data-testid="library-stop" :disabled="library.stopRequested" @click="library.stop">{{ library.stopRequested ? '正在停止…' : '停止' }}</button>
    </section>
    <div class="library-workspace">
      <section v-if="libraryTab==='sources'" class="library-panel library-sources">
        <div class="lib-panel-heading"><div><h2><i class="pi pi-box" />我的资料</h2></div><span class="lib-count">{{ library.sources.length }}</span></div>
        <div class="source-tools"><input v-model="sourceSearch" class="lib-input" placeholder="筛选包名或来源位置" aria-label="筛选资料来源"><button v-if="library.pending.length" class="lib-button primary" data-testid="library-index-pending" :disabled="busy" @click="library.index(library.pending.map(row => row.id))"><i class="pi pi-database"/>建立索引 · {{ library.pending.length }} 份</button></div>
        <details class="module-help source-maintenance" data-testid="library-maintenance"><summary><i class="pi pi-sliders-h"/>索引与来源维护</summary><div class="library-actions maintenance-actions"><button class="lib-button" data-testid="library-audit-all" :disabled="busy || !library.sources.length" @click="library.audit(library.sources.map(row => row.id))"><i class="pi pi-refresh"/>检查来源状态</button><button class="lib-button" data-testid="library-update-all" :disabled="busy || !library.sources.length" @click="library.index(library.sources.map(row => row.id))">更新全部索引</button></div><p>未变化的来源沿用索引。已有索引可离线搜索；打开或取回前会核对当前来源，原包始终保留。</p></details>
        <p v-if="library.loading && !library.sources.length" class="lib-empty">正在读取本地资料库…</p>
        <div v-else-if="!library.sources.length" class="lib-empty"><i class="pi pi-inbox text-3xl text-primary/60" /><strong>先加入一批资料</strong><span>选择压缩包，或扫描你指定的文件夹。<br>只建立目录索引，原文件保留。</span><button v-if="library.error" class="lib-link" @click="library.initialize">重新读取</button></div>
        <p v-else-if="!visibleSources.length" class="lib-empty">没有匹配的来源，试试其他包名。</p>
        <div v-else class="source-list custom-scrollbar" data-testid="library-source-list">
          <article v-for="row in visibleSources" :key="row.id" class="library-source" :class="{ expanded: expanded === row.id }" :data-source-id="row.id" :data-source-name="row.name" :data-source-status="row.status">
            <button class="source-summary" :aria-expanded="expanded === row.id" @click="expanded = expanded === row.id ? '' : row.id"><span class="source-icon"><i class="pi pi-box" /></span><span class="min-w-0 flex-1"><strong class="block break-all"><i v-if="library.labels(row.id).favorite" class="pi pi-star-fill text-amber-500 mr-1"/>{{ row.name }}</strong><span v-if="library.labels(row.id).tags.length" class="source-tags"><span v-for="tag in library.labels(row.id).tags" :key="tag">{{ tag }}</span></span><span class="source-status" :class="row.status">{{ libraryStatus[row.status] }}</span><span class="text-muted text-xs"> · {{ (row.indexedAt || row.status === 'ready') ? `${row.entryCount.toLocaleString()} 个文件 · ${row.format}` : row.format }}</span></span><i :class="expanded === row.id ? 'pi pi-chevron-up' : 'pi pi-chevron-down'" /></button>
            <div v-if="expanded === row.id" class="source-details"><p class="break-all">{{ row.path }}</p><p v-if="row.indexedAt" class="text-xs">上次索引：{{ new Date(row.indexedAt).toLocaleString() }}</p><p class="text-xs" :class="row.availability && !['available','unchecked'].includes(row.availability) ? 'source-reason' : 'text-muted'" data-testid="library-availability">{{ libraryAvailability[row.availability || 'unchecked']?.split(' · ')[0] }}{{ row.memberCount && row.memberCount > 1 ? ` · ${row.memberCount} 个分卷成员` : '' }}{{ row.encrypted ? ' · 密码资料' : '' }}</p><p v-if="row.availabilityNote" class="source-reason">{{ row.availabilityNote }}</p><p v-if="row.indexedAt && row.status !== 'ready'" class="text-xs text-muted">搜索保留上次索引，当前来源需处理后才能查看或取回。</p><p v-if="row.note" class="source-reason" data-testid="library-source-reason">{{ row.note }}</p><div class="library-actions"><button class="lib-link" data-testid="library-organize-source" :disabled="busy" @click="library.error='';organizing=row"><i class="pi pi-tags"/> 标签 / 收藏</button><button class="lib-link" data-testid="library-index-source" :disabled="busy" @click="refreshSource(row)">{{ row.status === 'ready' ? '刷新索引' : '建立 / 重试索引' }}</button><button class="lib-link" data-testid="library-source-credentials" :disabled="busy" @click="showCredentials(row)">密码 / 编码</button><button class="lib-link" data-testid="library-relocate-source" :disabled="busy" @click="relocateSource(row)">重新定位</button><button class="lib-link" data-testid="library-audit-source" :disabled="busy" @click="library.audit([row.id])">检查来源</button><button v-if="row.indexedAt || row.status === 'ready'" class="lib-link" @click="library.sourceId = row.id; libraryTab='search'">只搜此包</button><button class="lib-link text-muted" data-testid="library-remove-source" :disabled="busy" @click="removing = row">移出资料库</button></div></div>
          </article>
        </div>
        <div v-if="sourcePages > 1" class="lib-pagination"><button :disabled="sourcePage <= 1" @click="sourcePage--">上一页</button><span>{{ sourcePage }} / {{ sourcePages }}</span><button :disabled="sourcePage >= sourcePages" @click="sourcePage++">下一页</button></div>

      </section>
      <section v-else class="library-panel library-results">
        <div class="library-search"><label class="search-box"><i class="pi pi-search" /><input v-model="library.query" data-testid="library-query" aria-label="搜索包内文件名或路径" placeholder="例如：合同、说明.txt、项目/素材" maxlength="512"></label><div class="search-options"><details class="search-filter-details" data-testid="library-search-filters" :open="filterCount>0"><summary><i class="pi pi-filter"/>筛选条件<span v-if="filterCount" class="module-count">{{ filterCount }}</span><span class="filter-summary">{{ library.favoritesOnly?'收藏来源 · ':'' }}{{ library.tag || (library.sourceId?'指定来源':'全部资料') }}</span><i class="pi pi-chevron-down"/></summary><div class="filter-body"><div class="search-filters"><select v-model="library.sourceId" class="lib-input" data-testid="library-source-filter" aria-label="搜索来源"><option value="">所有已建库来源</option><option v-for="row in library.ready" :key="row.id" :value="row.id">{{ row.name }}</option></select><select v-model="library.category" class="lib-input" data-testid="library-category" aria-label="文件类型"><option value="all">所有文件类型</option><option value="document">文档</option><option value="image">图片</option><option value="audio">音频</option><option value="video">视频</option><option value="archive">压缩包</option></select></div><div class="search-filters"><select v-model="library.tag" class="lib-input" data-testid="library-tag-filter" aria-label="资料标签"><option value="">所有资料标签</option><option v-for="tag in library.tags" :key="tag" :value="tag">{{ tag }}</option><option v-if="library.tag && !library.tags.includes(library.tag)" :value="library.tag">{{ library.tag }}（暂无来源）</option></select><label class="favorite-filter"><input v-model="library.favoritesOnly" type="checkbox" data-testid="library-favorites-filter"><i class="pi pi-star-fill"/>只搜收藏来源</label></div></div></details><section class="library-collections"><div class="library-actions min-w-0"><i class="pi pi-bookmark text-primary"/><select v-model="savedSearchId" class="lib-input saved-search-select" data-testid="library-saved-searches" aria-label="常用搜索" @change="library.applySearch(savedSearchId)"><option value="">选择常用搜索</option><option v-for="saved in library.organization.searches" :key="saved.id" :value="saved.id">{{ saved.name }}</option></select><button class="lib-link" data-testid="library-save-search" @click="savingSearch=true">保存当前搜索</button><button v-if="savedSearchId" class="lib-link text-muted" data-testid="library-delete-search" @click="library.deleteSearch(savedSearchId);savedSearchId=''">删除这份条件</button></div></section></div></div>
        <div class="library-selection"><label><input type="checkbox" data-testid="library-select-page" :checked="!!library.hits.length && library.hits.every(retrieval.has)" :disabled="retrieval.busy || library.searching || !library.hits.length" @change="retrieval.togglePage(library.hits)">全选当前页</label><span>已选 {{ retrieval.items.length }} 个文件<span v-if="retrieval.items.length"> · 跨 {{ retrieval.groups.length }} 份来源</span></span><div class="library-actions"><button v-if="retrieval.items.length" class="lib-link" :disabled="retrieval.busy" @click="retrieval.clear">清空</button><button class="lib-button small primary" data-testid="library-batch-retrieval" :disabled="!retrieval.items.length || retrieval.busy" @click="retrievalVisible=true">批量取回</button></div></div>
        <p v-if="retrieval.error" class="source-reason px-5 text-xs" role="alert">{{ retrieval.error }}</p>
        <div class="results-caption"><span>{{ library.searching ? '正在查找…' : `找到 ${library.total.toLocaleString()} 个文件` }}</span><button class="lib-link" :disabled="library.searching" data-testid="library-refresh-search" @click="library.search">刷新结果</button></div>
        <div v-if="library.searchError" class="lib-empty" role="alert">搜索暂时不可用：{{ library.searchError }}<button class="lib-link" @click="library.search">重新搜索</button></div>
        <div v-else-if="!library.hits.length" class="lib-empty result-empty"><i class="pi pi-search text-3xl text-primary/50" /><strong>{{ library.ready.length ? '没有匹配的文件' : '建好索引，资料就能找到' }}</strong><span>{{ library.ready.length ? '试试更短的文件名，或更换来源与类型筛选。' : '加入资料并建立索引，就可以按文件名或路径跨包查找。' }}</span><button v-if="!library.ready.length" class="lib-button" data-testid="library-empty-manage" @click="libraryTab='sources'"><i class="pi pi-box"/>管理资料与索引</button></div>
        <div v-else class="library-hit-list" data-testid="library-results">
          <article v-for="hit in library.hits" :key="`${hit.sourceId}:${hit.path}`" class="library-hit" :data-entry-path="hit.path" :data-hit-source="hit.sourceName">
            <div class="hit-title"><input type="checkbox" data-testid="library-select-hit" :aria-label="'选择 '+hit.sourceName+' / '+hit.path" :checked="retrieval.has(hit)" :disabled="retrieval.busy" @change="retrieval.toggle(hit)"><i :class="['pi', ['png','jpg','jpeg','gif','webp','bmp'].includes(hit.extension) ? 'pi-image' : 'pi-file']" /><button class="hit-name" data-testid="library-locate-hit" :disabled="!!opening" @click="openHit(hit, 'locate')">{{ hit.name }}</button><span class="hit-size">{{ hit.sizeKnown === false ? '大小未统计' : libraryBytes(hit.size) }}</span></div>
            <p class="hit-path">{{ hit.path }}</p><div class="hit-origin"><span class="hit-source"><i class="pi pi-box" />{{ hit.sourceName }}<small>{{ hit.format }}</small></span><time v-if="hit.modified">{{ hit.modified }}</time><span v-if="hit.encrypted" class="text-primary"><i class="pi pi-lock" /> 密码资料</span><span :class="!hit.availability || ['available','unchecked'].includes(hit.availability) ? 'text-muted' : 'source-reason'" data-testid="library-hit-availability">{{ libraryAvailability[hit.availability || 'unchecked'] }}{{ hit.sourceStatus && !['ready','indexing'].includes(hit.sourceStatus) ? ` · ${libraryStatus[hit.sourceStatus as LibrarySource['status']]}` : '' }}</span></div>
            <div class="hit-bottom"><details class="hit-source-path"><summary :title="hit.sourcePath">来源位置 <i class="pi pi-angle-down"/></summary><p>{{ hit.sourcePath }}</p></details><div class="library-actions"><button v-if="['png','jpg','jpeg','gif','webp','bmp','svg','ico','avif'].includes(hit.extension.toLowerCase())" class="lib-button small" data-testid="library-hit-read" :disabled="!!opening" @click="openHit(hit, 'read')"><i class="pi pi-images"/>连续阅读</button><button class="lib-button small" data-testid="library-preview-hit" :disabled="!!opening" @click="openHit(hit, 'preview')"><i class="pi pi-eye" />查看</button><button class="lib-button small primary" data-testid="library-extract-hit" :disabled="!!opening" @click="openHit(hit, 'extract')"><i class="pi pi-download" />取回</button></div></div>
          </article>
        </div>
        <div v-if="resultPages > 1" class="lib-pagination"><button data-testid="library-prev-page" :disabled="library.page <= 1 || library.searching" @click="resultPage(library.page - 1)">上一页</button><span>{{ library.page }} / {{ resultPages }} · 每页 50 条</span><button data-testid="library-next-page" :disabled="library.page >= resultPages || library.searching" @click="resultPage(library.page + 1)">下一页</button></div>
      </section>
    </div>
    <LibraryOrganizeDialog v-if="organizing" :source="organizing" @close="organizing=null" />
    <LibraryRetrievalDialog v-if="retrievalVisible" @close="retrievalVisible=false" @fix="fixRetrieval" @queue="retrievalVisible=false;router.push('/decompress')" />
